const tl = gsap.timeline({
  scrollTrigger: {
    trigger: container,
    scroller,
    start: 'top bottom',
    end: 'bottom top',
    scrub: true,
  },
});

tl.to(titleRef.current, { y: -50 }, 0)
  .to(imagesRef.current[1], { y: -150 }, 0)
  .to(imagesRef.current[2], { y: -255 }, 0);

lettersRef.current.forEach((letter) => {
  if (!letter) return;
  tl.to(letter, { y: gsap.utils.random(-100, -30) }, 0);
});
